PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE pins (
    id          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
    name        TEXT NOT NULL,
    description TEXT,
    type        TEXT NOT NULL,
    x           REAL NOT NULL,
    y           REAL NOT NULL
);
CREATE TABLE images (
    id          TEXT    NOT NULL,
    pin_id      TEXT    NOT NULL REFERENCES pins(id) ON DELETE CASCADE,
    mime        TEXT    NOT NULL,
    chunk_index INTEGER NOT NULL DEFAULT 0,
    data        TEXT    NOT NULL, description TEXT, author TEXT, year INTEGER,
    PRIMARY KEY (id, chunk_index)
);
